WITH cust_total AS ( SELECT c.c_customer_id, SUM(sr.sr_return_amt_inc_tax) AS total_return, RANK() OVER (ORDER BY SUM(sr.sr_return_amt_inc_tax) DESC) AS total_return_rank FROM store_returns sr JOIN customer c ON sr.sr_customer_sk = c.c_customer_sk JOIN date_dim d ON sr.sr_returned_date_sk = d.d_date_sk WHERE d.d_year = 2022 GROUP BY c.c_customer_id ) SELECT sr.sr_ticket_number, c.c_customer_id, d.d_date AS return_date, sr.sr_return_amt_inc_tax, hd.hd_income_band_sk, AVG(sr.sr_return_amt_inc_tax) OVER (PARTITION BY hd.hd_demo_sk) AS avg_return_by_demo, sr.sr_return_amt_inc_tax - AVG(sr.sr_return_amt_inc_tax) OVER (PARTITION BY hd.hd_demo_sk) AS deviation_from_avg, SUM(sr.sr_return_amt_inc_tax) OVER (PARTITION BY c.c_customer_id ORDER BY d.d_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_return_amount, ct.total_return, ct.total_return_rank, CASE WHEN sr.sr_return_amt_inc_tax > 2 * AVG(sr.sr_return_amt_inc_tax) OVER (PARTITION BY hd.hd_demo_sk) THEN 'Outlier High' WHEN sr.sr_return_amt_inc_tax < 0.5 * AVG(sr.sr_return_amt_inc_tax) OVER (PARTITION BY hd.hd_demo_sk) THEN 'Outlier Low' ELSE 'Normal' END AS anomaly_flag FROM store_returns sr JOIN customer c ON sr.sr_customer_sk = c.c_customer_sk JOIN household_demographics hd ON sr.sr_hdemo_sk = hd.hd_demo_sk JOIN date_dim d ON sr.sr_returned_date_sk = d.d_date_sk JOIN cust_total ct ON ct.c_customer_id = c.c_customer_id WHERE d.d_year = 2022 ORDER BY c.c_customer_id, d.d_date
